<?php
if(!defined('ABSPATH'))exit;
function dgs_mark_default_day($period){$today=dgs_att_jdate(dgs_mg_now()->format('Y-m-d'));return substr($today,0,7)===$period?$today:$period.'-01';}
function dgs_mark_fields($d,$ctx,$old=null){
 $raw=$d['evaluation_date']??($old?($old->evaluation_date?dgs_att_jdate($old->evaluation_date):''):dgs_mark_default_day($ctx['period']));if($old&&!$old->evaluation_date&&$raw===''){$title=sanitize_text_field((string)($d['title']??($old->title??'')));if(dgs_edu_length($title)>200)return dgs_edu_error('title','عنوان ارزیابی حداکثر ۲۰۰ نویسه باشد.');return array('evaluation_date'=>null,'title'=>$title,'period'=>$ctx['period']);}$g=is_string($raw)?dgs_att_parse_day($raw,$ctx['year']):false;
 if(!$g||$g>dgs_mg_now()->format('Y-m-d'))return dgs_edu_error('date','تاریخ ارزیابی معتبر در همین سال و حداکثر امروز را وارد کنید.');$period=substr(dgs_att_jdate($g),0,7);
 if(!$old&&$period!==$ctx['period'])return dgs_edu_error('date','تاریخ ارزیابی باید در ماه انتخابی باشد.');
 $title=sanitize_text_field((string)($d['title']??($old->title??'ارزیابی کلاسی')));if(dgs_edu_length($title)>200)return dgs_edu_error('title','عنوان ارزیابی حداکثر ۲۰۰ نویسه باشد.');
 return array('evaluation_date'=>$g,'title'=>$title,'period'=>$period);
}
function dgs_mark_date_label($r){return !empty($r->evaluation_date)?dgs_fa_digits(dgs_att_jdate($r->evaluation_date)):'تاریخ ارزیابی در نسخه قبلی ثبت نشده';}
function dgs_mark_actor($id){$u=get_userdata($id);return $u?$u->display_name:'سیستم';}
function dgs_manager_marks_link($year,$class,$period,$extra=array()){return dgs_school_url('grades',$year,array_merge(array('marks_class'=>$class,'grade_period'=>$period),$extra));}
function dgs_manager_marks($year){
 if(!current_user_can('dgs_manage_education'))return '';
 $classes=dgs_edu_classes($year);$options=[];foreach($classes as $c)$options[$c->id]=dgs_edu_grade_label($c->grade).' '.$c->title;
 $cid=absint(dgs_att_get('marks_class'));if(!isset($options[$cid]))$cid=(int)array_key_first($options);$period=dgs_grade_period(dgs_att_get('grade_period'),$year)?: (dgs_mg_effective($year)?:substr($year,0,4).'-07');$uid=absint(dgs_att_get('marks_student'));$subject=absint(dgs_att_get('marks_subject'));
 $h='<div class="mg-page"><header class="mg-heading"><h2>'.dgs_portal_icon('grades').' دفتر نمرات دانش‌آموزان</h2><p>کلاس ← دانش‌آموز ← میانگین ماهانه درس‌ها ← جزئیات و اصلاح ثبت‌ها</p></header><section class="mg-card"><form method="get" class="dgx-filter"><input type="hidden" name="dg_tab" value="grades"><input type="hidden" name="dg_year" value="'.esc_attr($year).'">'.dgs_edu_select('marks_class','کلاس',$options,$cid).dgs_edu_select('grade_period','ماه',dgs_mg_periods($year),$period).'<button class="dg-btn">نمایش</button></form><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_school_url('grades',$year,array('grade_mode'=>'entry','grade_period'=>$period))).'">ثبت نمره / تنظیم مهلت و نهایی‌سازی</a></section>';
 if(!$cid)return $h.dgs_empty('هنوز کلاسی ثبت نشده است.').'</div>';
 $students=dgs_mg_roster($cid,$year);$members=wp_list_pluck($students,'display_name','ID');
 // Include students with historical marks in this class/month after a transfer.
 global $wpdb;$t=dgs_mg_tables();$e=dgs_edu_tables();$past=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT u.ID,u.display_name FROM {$t['entries']} m JOIN {$wpdb->users} u ON u.ID=m.student_id WHERE m.class_id=%d AND m.school_year=%s AND m.period=%s AND m.deleted=0",$cid,$year,$period));foreach($past as $u)$members[$u->ID]=$u->display_name;
 if(!$uid||!isset($members[$uid])){$h.='<section class="mg-card"><h3>دانش‌آموزان '.esc_html($options[$cid]).'</h3>'.dgs_edu_table_start(array('نام دانش‌آموز','نمرات ماهانه'));foreach($members as $id=>$name)$h.='<tr><td>'.esc_html($name).'</td><td><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_manager_marks_link($year,$cid,$period,array('marks_student'=>$id))).'">جزئیات نمرات ماه</a></td></tr>';return $h.'</tbody></table></div></section></div>';}
 $h.='<section class="mg-card"><h3>'.esc_html($members[$uid]).' — '.esc_html(dgs_mg_label($period)).'</h3><a href="'.esc_url(dgs_manager_marks_link($year,$cid,$period)).'">بازگشت به دانش‌آموزان کلاس</a>'.dgs_edu_table_start(array('درس','میانگین نمره‌ها','تعداد نمره','جزئیات'));
 $rows=$wpdb->get_results($wpdb->prepare("SELECT s.id,s.title,COUNT(CASE WHEN m.kind='grade' THEN 1 END) AS n,AVG(CASE WHEN m.kind='grade' THEN m.amount END) AS mean FROM {$e['subjects']} s LEFT JOIN {$t['entries']} m ON m.subject_id=s.id AND m.class_id=%d AND m.student_id=%d AND m.period=%s AND m.deleted=0 WHERE EXISTS (SELECT 1 FROM {$e['teaching']} a WHERE a.class_id=%d AND a.subject_id=s.id) OR EXISTS (SELECT 1 FROM {$t['entries']} p WHERE p.class_id=%d AND p.student_id=%d AND p.period=%s AND p.subject_id=s.id AND p.deleted=0) GROUP BY s.id,s.title ORDER BY s.title",$cid,$uid,$period,$cid,$cid,$uid,$period));
 $g=dgs_grade_table();$legacy=$wpdb->get_results($wpdb->prepare("SELECT subject_id,score FROM $g WHERE class_id=%d AND student_id=%d AND period=%s",$cid,$uid,$period),OBJECT_K);$valid=[];foreach($rows as $r){$valid[(int)$r->id]=$r;$h.='<tr><td>'.esc_html($r->title).'</td><td>'.($r->n?esc_html(dgs_mg_fmt(dgs_mg_cents(number_format((float)$r->mean,2,'.','')))):(isset($legacy[$r->id])&&dgs_mg_view_state(['year'=>$year,'class_id'=>$cid,'subject_id'=>$r->id,'period'=>$period])->status==='legacy'?esc_html(dgs_mg_fmt(dgs_mg_cents($legacy[$r->id]->score))).'<small>نمره ماهانه پیشین؛ بدون جزئیات روزانه</small>':'—')).'</td><td>'.esc_html(dgs_fa_digits($r->n)).'</td><td><a href="'.esc_url(dgs_manager_marks_link($year,$cid,$period,array('marks_student'=>$uid,'marks_subject'=>$r->id))).'#mg-history">جزئیات / اصلاح</a></td></tr>';}$h.='</tbody></table></div></section>';
 if(isset($valid[$subject])){$ctx=['year'=>$year,'class_id'=>$cid,'subject_id'=>$subject,'period'=>$period];$detail=dgs_mg_history_card($ctx,dgs_mg_view_state($ctx),$uid,$members[$uid].' — '.$valid[$subject]->title,true);$detail=str_replace('<input type="hidden" name="action"', '<input type="hidden" name="return_manager" value="1"><input type="hidden" name="action"',$detail);$h.='<section class="mg-card"><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_school_url('grades',$year,['grade_mode'=>'entry','grade_pair'=>$cid.':'.$subject,'grade_period'=>$period,'mg_student'=>$uid])).'">ثبت نمره جدید در این درس</a></section>'.$detail;}
 return $h.'</div>';
}
